<?php
declare(strict_types=1);
require_once __DIR__ . '/_helper.php';
use Illuminate\Database\Capsule\Manager as Capsule;
$id_entitas=po_id_entitas(); $id=(int)($_GET['id']??0); $no=trim((string)($_GET['no']??''));
$q=Capsule::table('tb_pesanan_penjualan as pp')->leftJoin('tb_pelanggan as p','p.id_pelanggan','=','pp.id_pelanggan')->where('pp.id_entitas',$id_entitas);
if($id>0)$q->where('pp.id_pesanan_penjualan',$id); elseif($no!=='')$q->where('pp.no_pesanan_penjualan',$no); else $q->whereRaw('1=0');
$pesanan=$q->select(['pp.*','p.nama_pelanggan','p.no_hp','p.email','p.alamat'])->first();
$detail=collect(); if($pesanan){$detail=Capsule::table('tb_pesanan_penjualan_detail as d')->join('tb_produk as pr','pr.id_produk','=','d.id_produk')->where('d.id_pesanan_penjualan',(int)$pesanan->id_pesanan_penjualan)->select(['d.*','pr.kode_produk','pr.nama_produk'])->orderBy('d.id_pesanan_penjualan_detail')->get();}
$paymentSetting=po_payment_setting($id_entitas); $qrisManualImageUrl=po_public_file_url((string)($paymentSetting->qris_image_path??'')); $latestProof=$pesanan?po_latest_payment_proof((int)$pesanan->id_pesanan_penjualan):null; $metode=$pesanan?(string)($pesanan->metode_pembayaran_online??'cod'):'cod'; $total=$pesanan?(float)($pesanan->nominal_pembayaran_online??$pesanan->total??0):0;
$bankName=trim((string)($paymentSetting->nama_bank??'')); $bankAccount=trim((string)($paymentSetting->nomor_rekening??'')); $bankHolder=trim((string)($paymentSetting->atas_nama_rekening??''));
$canCancel=$pesanan && !in_array((string)($pesanan->status_pesanan??''),['diproses','selesai','batal'],true) && !in_array((string)($pesanan->status_pembayaran_online??''),['lunas','paid','settlement'],true);
?>
