und:#fff;padding:16px;object-fit:contain;display:block;margin:10px auto}.proof-img{min-height:auto;max-height:420px}.gateway-status{display:inline-flex;border-radius:999px;padding:7px 11px;font-size:12px;font-weight:900}.gateway-status.ok{background:#ecfdf5;color:#166534}.gateway-status.warn{background:#fff7ed;color:#9a3412}.gateway-status.err{background:#fef2f2;color:#991b1b}.proof-box{border:1px dashed rgba(109,93,252,.35);border-radius:18px;padding:16px;margin:16px;background:linear-gradient(135deg,#eef2ff,#fff7ed)}.control{width:100%;border:1px solid var(--line);border-radius:14px;padding:12px;margin-top:8px}.btn{border:0;border-radius:999px;padding:12px 16px;font-weight:900;cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:8px}.btn-primary{background:linear-gradient(135deg,var(--blue),var(--purple));color:#fff}.btn-orange{background:linear-gradient(135deg,var(--orange),var(--purple));color:#fff}.btn-soft{background:#fff;border:1px solid var(--line);color:#1e293b}.btn-danger{background:#fff;border:1px solid #fecaca;color:#b91c1c}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.alert{border-radius:16px;padding:12px;margin-bottom:14px}.ok{background:#ecfdf5;color:#166534}.err{background:#fef2f2;color:#991b1b}@media(max-width:760px){.grid,.pay-grid{grid-template-columns:1fr}.head h1{font-size:28px}.qris-img{min-height:340px;max-width:100%}}
