<section class="section"><h2>Produk Dipesan</h2><table><thead><tr><th>Produk</th><th class="right">Qty</th><th class="right">Harga</th><th class="right">Subtotal</th></tr></thead><tbody><?php foreach($detail as $d): ?><tr><td><strong><?= po_esc($d->nama_produk) ?></strong><br><span style="color:#64748b"><?= po_esc($d->kode_produk) ?></span></td><td class="right"><?= po_qty($d->qty) ?></td><td class="right"><?= po_uang($d->harga) ?></td><td class="right"><strong><?= po_uang($d->subtotal) ?></strong></td></tr><?php endforeach; ?><tr><td colspan="3" class="right"><strong>Total</strong></td><td class="right"><strong class="total"><?= po_uang($total) ?></strong></td></tr></tbody></table></section>
<section class="section"><h2>Informasi Pembayaran</h2><div class="pay-grid"><div class="pay-card"><div class="label">Metode Pembayaran</div><div class="val"><?= po_esc(po_payment_method_label($metode)) ?></div><div class="label" style="margin-top:12px">Status Pembayaran</div><div class="val"><?= po_esc(po_payment_status_label($pesanan->status_pembayaran_online ?? 'belum_bayar')) ?></div><div class="label" style="margin-top:12px">Nominal</div><div class="val total"><?= po_uang($total) ?></div><?php if($metode==='transfer'): ?><hr><div class="label">Nama Bank</div><div class="val"><?= po_esc($bankName?:'-') ?></div><div class="label">Nama Nasabah</div><div class="val"><?= po_esc($bankHolder?:'-') ?></div><div class="label">No Rekening</div><div class="val rekening-copy"><span id="noRekeningText"><?= po_esc($bankAccount?:'-') ?></span><button type="button" class="copy-rek-btn" onclick="navigator.clipboard?navigator.clipboard.writeText(document.getElementById('noRekeningText').innerText).then(()=>this.innerText='Tersalin'):alert(document.getElementById('noRekeningText').innerText)">Salin</button></div><?php endif; ?></div><div class="pay-card"><?php if($latestProof): ?><div class="label">Bukti Pembayaran Terakhir</div><?php $proofUrl=po_public_file_url((string)$latestProof->file_bukti); if($proofUrl): ?><img class="proof-img" src="<?= po_esc($proofUrl) ?>" alt="Bukti bayar"><?php endif; ?><div class="val"><?= po_esc(po_payment_status_label($latestProof->status_verifikasi ?? 'menunggu_verifikasi')) ?></div><?php else: ?><div class="label">Bukti pembayaran</div><p style="color:#64748b">Belum ada bukti pembayaran yang diupload.</p><?php endif; ?></div></div><?php if($metode==='qris'): ?><div style="padding:16px"><div class="qris-panel"><h3>QRIS Manual</h3><?php if($qrisManualImageUrl): ?><img class="qris-img" src="<?= po_esc($qrisManualImageUrl) ?>" alt="QRIS Manual"><div class="actions"><a class="btn btn-soft" href="<?= po_esc($qrisManualImageUrl) ?>" download>Simpan Gambar QRIS</a></div><?php else: ?><div class="alert err">Gambar QRIS manual belum diupload.</div><?php endif; ?></div></div><?php endif; ?><?php if(in_array($metode,['transfer','qris'],true)): ?><form class="proof-box" method="post" enctype="multipart/form-data" action="<?= po_esc(po_url('upload_bukti.php')) ?>"><strong>Upload / ganti bukti pembayaran</strong><input type="hidden" name="id_entitas" value="<?= (int)$id_entitas ?>"><input type="hidden" name="id_pesanan_penjualan" value="<?= (int)$pesanan->id_pesanan_penjualan ?>"><input type="hidden" name="no_pesanan_penjualan" value="<?= po_esc($pesanan->no_pesanan_penjualan) ?>"><input type="hidden" name="no_hp" value="<?= po_esc($pesanan->no_hp??'') ?>"><input type="hidden" name="nominal_bayar" value="<?= po_esc((string)$total) ?>"><input type="hidden" name="nama_pengirim" value="<?= po_esc($pesanan->nama_pelanggan??'') ?>"><input type="file" class="control" name="file_bukti" accept="image/*,application/pdf" required><button class="btn btn-primary" style="margin-top:10px" type="submit">Upload Bukti</button></form><?php endif; ?></section>
<div class="actions"><a class="btn btn-primary" href="<?= po_esc(po_url('simpan_jpg.php?id='.(int)$pesanan->id_pesanan_penjualan.'&entitas='.(int)$id_entitas)) ?>">Simpan Kode JPG</a><a class="btn btn-orange" href="<?= po_esc(po_url('index.php?entitas='.(int)$id_entitas)) ?>">Kembali ke Halaman Awal</a><a class="btn btn-soft" href="<?= po_esc(po_url('cek.php?entitas='.(int)$id_entitas.'&no_hp='.urlencode((string)($pesanan->no_hp??'')))) ?>">Cek Pesanan</a><?php if($canCancel): ?><form method="post" action="<?= po_esc(po_url('batal.php')) ?>" onsubmit="return confirm('Batalkan pesanan ini?')"><input type="hidden" name="id_entitas" value="<?= (int)$id_entitas ?>"><input type="hidden" name="id_pesanan_penjualan" value="<?= (int)$pesanan->id_pesanan_penjualan ?>"><input type="hidden" name="no_hp" value="<?= po_esc($pesanan->no_hp??'') ?>"><button class="btn btn-danger" type="submit">Batalkan Pesanan</button></form><?php endif; ?></div>
<?php endif; ?></div></div></div></body></html>
